//! Standalone Rust files generated from grammar files.

use crate::{Diagnostic, Options, Source, TextSource};

/// Where generated code finds the runtime.
#[derive(Clone, Debug)]
pub enum Runtime {
    /// The `prpr-runtime` crate or a module written by [`runtime_module`], at a path.
    Path(String),
    /// A module included in the generated file.
    Inline,
}

/// The name of the inlined runtime module.
pub const INLINE_RUNTIME: &str = "__prpr_runtime";

// Generated code, including the runtime, is exempt from the license of prpr (see README.md).
const LICENSE_NOTE: &str =
    "It may be used under any terms (see https://github.com/tanakh/prpr#license).";

/// Generates the source of a Rust module from the text of a grammar.
pub fn generate(text: &str, runtime: &Runtime) -> Result<String, Vec<Diagnostic>> {
    let path = match runtime {
        Runtime::Path(path) => path.as_str(),
        Runtime::Inline => INLINE_RUNTIME,
    };
    let opts = Options {
        runtime: path.parse().map_err(|_| {
            vec![Diagnostic::error(
                Default::default(),
                format!("invalid runtime path `{path}`"),
            )]
        })?,
        // An inlined runtime always matches.
        check_version: matches!(runtime, Runtime::Path(_)),
    };
    let src = TextSource(text);
    let tokens = crate::compile(&src, &opts)?;
    // The compiler of a proc-macro would report invalid Rust code in the grammar; here, `syn`
    // does, at the token where it found the error.
    let file: syn::File = syn::parse2(tokens).map_err(|e| {
        let d = match src.locate(e.span()) {
            Some(span) => Diagnostic::error(span, format!("invalid Rust code: {e}")),
            None => Diagnostic::error(
                Default::default(),
                format!("internal error: generated code does not parse: {e}"),
            ),
        };
        vec![d]
    })?;
    let mut out = format!(
        "// This file was generated by prpr {}. Do not edit it.\n// {LICENSE_NOTE}\n\n",
        env!("CARGO_PKG_VERSION")
    );
    out.push_str(&prettyplease::unparse(&file));
    if let Runtime::Inline = runtime {
        out.push_str(&format!(
            "\n#[doc(hidden)]\n#[allow(dead_code, clippy::all)]\npub mod {INLINE_RUNTIME} {{\nextern crate alloc;\n\n{}}}\n",
            prpr_runtime::SOURCE
        ));
    }
    Ok(out)
}

/// The runtime as the source of a module, for generated files that refer to it by a path.
pub fn runtime_module() -> String {
    format!(
        "// The runtime of prpr {}. Do not edit it.\n// {LICENSE_NOTE}\n\n#![allow(dead_code, clippy::all)]\n\nextern crate alloc;\n\n{}",
        env!("CARGO_PKG_VERSION"),
        prpr_runtime::SOURCE
    )
}
